parameters.jsCode:
const raw = $input.first().json.content[0].text;
let scoring;
try {
  scoring = JSON.parse(raw);
} catch (e) {
  const m = raw.match(/\{[\s\S]*\}/);
  try { scoring = JSON.parse(m[0]); } catch { scoring = { score: 50, grade: 'C', icp_fit: 'moderate', score_breakdown: {}, strengths: [], concerns: [], recommended_action: 'nurture', outreach_angle: '', next_step: 'Manual review needed' }; }
}

const lead = $('Extract Lead Data').first().json;
const scoreEmoji = scoring.score >= 80 ? '🟢' : scoring.score >= 60 ? '🟡' : '🔴';

return [{ json: {
  ...scoring,
  ...lead,
  score_emoji: scoreEmoji,
  scored_at: new Date().toISOString()
}}];
